--
-- Table structure for table `adminnotification_inbox`
--

DROP TABLE IF EXISTS `adminnotification_inbox`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `adminnotification_inbox` (
  `notification_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'Notification ID',
  `severity` smallint unsigned NOT NULL DEFAULT '0' COMMENT 'Problem type',
  `date_added` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'Create date',
  `title` varchar(255) NOT NULL COMMENT 'Title',
  `description` text COMMENT 'Description',
  `url` varchar(255) DEFAULT NULL COMMENT 'Url',
  `is_read` smallint unsigned NOT NULL DEFAULT '0' COMMENT 'Flag if notification read',
  `is_remove` smallint unsigned NOT NULL DEFAULT '0' COMMENT 'Flag if notification might be removed',
  PRIMARY KEY (`notification_id`),
  KEY `ADMINNOTIFICATION_INBOX_SEVERITY` (`severity`),
  KEY `ADMINNOTIFICATION_INBOX_IS_READ` (`is_read`),
  KEY `ADMINNOTIFICATION_INBOX_IS_REMOVE` (`is_remove`)
) ENGINE=InnoDB AUTO_INCREMENT=37 DEFAULT CHARSET=utf8mb3 COMMENT='Adminnotification Inbox';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `adminnotification_inbox`
--

LOCK TABLES `adminnotification_inbox` WRITE;
/*!40000 ALTER TABLE `adminnotification_inbox` DISABLE KEYS */;
INSERT INTO `adminnotification_inbox` VALUES (1,4,'2020-12-16 03:07:55','Disable Notice','To improve performance, collecting statistics for the Magento Report module is disabled by default. \nYou can enable it in System Config.','',0,0),(2,3,'2020-12-16 03:49:11','New version 2.9.7 of Magefan Magento 2 Blog Extension is now available.',' You can download the new version from Magefan Store or update it via composer. Get us in touch if you need our help with an update or you have any questions.\n                                    https://magefan.com/magento2-blog-extension?version=2.9.7\n                                 ','https://magefan.com/magento2-blog-extension?version=2.9.7',0,0),(3,4,'2020-12-16 03:49:11','FAQ: How to configure &quot;read more&quot; in your Magento 2 blog post',' If you still don&#039;t know how to configure read more functionality in your magento 2 blog post, please read this article.\n                    Online documentation for Magento 2 blog extension is also available on our website. http://goo.gl/XOEdpy ','http://magefan.com/blog/add-read-more-tag-to-blog-post-content/?from=notification1',0,0),(4,4,'2021-01-08 21:35:55','Happy new year! Is Your Website Selling as Much as It Can? Watch our on-demand webinar and learn how to turn your website into a conversion machine.','Watch our on-demand webinar: Is Your Website Selling As Much As It Can? Digital Strategist Ereika Stimley and eCommerce Consultant Corey Gelato will walk you through a website self-assessment and live demo that will help you uncover opportunities to increase conversions and grow revenues. Watch now: https://bit.ly/2EAujMc','https://bit.ly/2EAujMc',0,0),(5,4,'2021-01-14 01:32:42','You&#039;re invited to our webinar: Is Magento Commerce or Open Source right for you? ','Magento Commerce and Magento Open Source may sound alike, but each offers sharply distinct benefits. To get the facts, sign up for our webinar Is Magento Commerce or Open Source right for you? at 10:00 AM PT on February 4th. Register now: http://bit.ly/3icfnTM','http://bit.ly/3icfnTM',0,0),(6,4,'2021-02-10 15:06:05','Magento Commerce 2.4.2 delivers important security updates and features to help secure and optimize your store','Magento Open Source 2.4.2, along with security-only patches 2.3.6-p1 and 2.4.1-p1, is now generally available. The latest release of Magento Open Source includes important security enhancements along with new functionality and platform quality improvements. With these important updates we strongly recommend that you upgrade to ensure your sites maintain the highest level of security. You can review the release notes for more information about all of the enhancements. Learn how this release can help you save time and maximize resources at Magento.com/blog. ','https://devdocs.magento.com/guides/v2.4/release-notes/bk-release-notes.html',0,0),(7,4,'2021-02-10 15:08:37','Register now for Summit 2021 and stay ahead of commerce trends ','Learn best practices from digital commerce experts during two days of live keynotes, sessions, and sneak peeks. Understand the latest digital commerce trends, discover industry best practices, and network with peers around the world. Register now!','https://summit.adobe.com/na/?utm_source=m1o&amp;utm_medium=rss&amp;utm_campaign=NA_210427_12576_RSS_EVTR_ACOM_FM_Summit_2021_M1_OS',0,0),(8,4,'2021-02-22 23:52:27','Quarterly Business Planning - reach out to us today to get your free site assessment.','Would you like a free site assessment? Our best-in-breed commerce solution gives your business unmatched agility and scalability. It&#039;s time to experience limitless eCommerce with no comprises. Learn more: https://bit.ly/3lcgILt','https://bit.ly/3lcgILt',0,0),(9,4,'2021-03-23 00:33:54','You&#039;re invited to our webinar this week: How digital commerce can scale B2B selling','Digital commerce is fast becoming the default way to buy—even for B2B customers. In just 8 weeks, Byrne Electrical, the leading manufacturer of power and data solutions for numerous industries, launched an eCommerce portal for more than 1,100 of their customers. To learn how they did it, join George Fabis, Director of IT for Byrne, and Slava Kravchuk, CEO &amp; Founder of Atwix, a Magento Commerce solutions partner, for a live discussion on Thursday, March 25. Register Now: https://bit.ly/3r1MCvG','https://bit.ly/3r1MCvG',0,0),(10,3,'2021-04-12 08:15:30','New version 2.9.8 of Magefan Magento 2 Blog Extension is now available.',' You can download the new version from Magefan Store or update it via composer. Get us in touch if you need our help with an update or you have any questions.\n                                    https://magefan.com/magento2-blog-extension?version=2.9.8\n                                 ','https://magefan.com/magento2-blog-extension?version=2.9.8',0,0),(11,4,'2021-05-11 20:44:41','Magento Open Source 2.4.2-p1 &amp; 2.3.7 deliver important security updates','The latest releases of Magento Open Source – 2.3.7 and 2.4.2-p1 – are now generally available. The latest release of Magento Open Source includes important security updates. With these important updates we strongly recommend that you upgrade to ensure your sites maintain the highest level of security. You can review the release notes for more information about all of the updates. Learn how this release can help you save time and maximize resources at Magento.com/blog.','https://devdocs.magento.com/guides/v2.3/release-notes/bk-release-notes.html ',0,0),(12,3,'2021-05-24 03:01:35','New version 2.10.1 of Magefan Magento 2 Blog Extension is now available.',' You can download the new version from Magefan Store or update it via composer. Get us in touch if you need our help with an update or you have any questions.\n                                    https://magefan.com/magento2-blog-extension?version=2.10.1\n                                 ','https://magefan.com/magento2-blog-extension?version=2.10.1',0,0),(13,3,'2021-07-22 02:54:57','New version 2.10.2 of Magefan Magento 2 Blog Extension is now available.',' You can download the new version from Magefan Store or update it via composer. Get us in touch if you need our help with an update or you have any questions.\n                                    https://magefan.com/magento2-blog-extension?version=2.10.2\n                                 ','https://magefan.com/magento2-blog-extension?version=2.10.2',0,0),(14,3,'2021-08-03 00:00:00','New FREE Magento 2 Facebook Pixel Extension','Integrate Facebook Pixel just in a few clicks with the new FREE Magento 2 Facebook Pixel Extension. Hurry up to try it out! https://magefan.com/magento-2-facebook-pixel-extension','https://magefan.com/magento-2-facebook-pixel-extension?utm_source=website&amp;utm_medium=admin_notification&amp;utm_campaign=new_extension_fb_pixel',0,0),(15,4,'2021-08-10 17:53:11','Magento Open Source 2.4.3 available today!','Magento Open Source 2.4.3, along with security-only patches 2.4.2-p1 and 2.3.7-p2, is now generally available. Magento Open Source 2.4.3 includes 33 security and 370+ quality improvements, along with performance and scale enhancements.  With these important updates, we strongly recommend that you upgrade to maintain the highest level of security for your sites. Learn how this release can help you save time and maximize resources in our release blog. ','http://magento.com/blog/magento-news/get-ready-your-peak-season-adobe-commerce-243',0,0),(16,3,'2021-09-30 09:11:26','New version 2.10.3 of Magefan Magento 2 Blog Extension is now available.',' You can download the new version from Magefan Store or update it via composer. Get us in touch if you need our help with an update or you have any questions.\n                                    https://magefan.com/magento2-blog-extension?version=2.10.3\n                                 ','https://magefan.com/magento2-blog-extension?version=2.10.3',0,0),(17,4,'2021-10-01 14:44:47','New, Simplified Upgrade Process and Lifecycle Policy